from src.nodes.base import BaseNode
from src.runtime.assets.acquisition import get_library_index
import json

class Hou_Mcp_Library_Index(BaseNode):
    name = "hou_mcp_library_index"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("action",   "string", widget_type="text", default="search")
        self.add_input("query",    "string", widget_type="text", default="")
        self.add_input("category", "string", widget_type="text", default="")
        self.add_input("provider", "string", widget_type="text", default="")
        self.add_input("limit",    "int",    widget_type="int",  default=50)
        # [AUTO-GENERATED-PORTS-END]
        self.add_output("results_json", "string")
        self.add_output("result_count", "int")

    async def execute(self, inputs):
        action   = str(inputs.get("action",   "search") or "search").strip().lower()
        query    = str(inputs.get("query",    "") or "")
        category = str(inputs.get("category", "") or "")
        provider = str(inputs.get("provider", "") or "")
        limit    = int(inputs.get("limit",    50) or 50)
        idx = get_library_index()
        try:
            if action == "search":
                result = idx.search(query=query, category=category, provider=provider, limit=limit)
                self.log_info(f"Library index search '{query}': {result.total_hits} hits ({len(result.entries)} returned).")
                return {"results_json": json.dumps(result.to_dict(), sort_keys=True, default=str),
                        "result_count": len(result.entries), "exec_out": True}
            elif action == "stats":
                stats = idx.get_statistics()
                self.log_info(f"Library index stats: {stats['total_entries']} entries.")
                return {"results_json": json.dumps(stats, sort_keys=True, default=str),
                        "result_count": stats.get("total_entries", 0), "exec_out": True}
            elif action == "save":
                ok = idx.save()
                self.log_info(f"Library index save: {'ok' if ok else 'failed'}.")
                return {"results_json": json.dumps({"saved": ok}, sort_keys=True),
                        "result_count": 0, "exec_out": True}
            elif action == "providers":
                provs = idx.list_providers()
                return {"results_json": json.dumps({"providers": provs}, sort_keys=True),
                        "result_count": len(provs), "exec_out": True}
            elif action == "categories":
                cats = idx.list_categories()
                return {"results_json": json.dumps({"categories": cats}, sort_keys=True),
                        "result_count": len(cats), "exec_out": True}
            else:
                self.log_error(f"Unknown action: {action!r}. Use: search, stats, save, providers, categories.")
                return {"results_json": "{}", "result_count": 0, "exec_out": True}
        except Exception as exc:
            self.log_error(f"Library index failed: {exc}")
            return {"results_json": "{}", "result_count": 0, "exec_out": True}

def register_node():
    return Hou_Mcp_Library_Index
